style.css:
@-moz-document url-prefix("http") {
/* DÁN TOÀN BỘ CODE CỦA M VÀO ĐÂY */
	  :root {
  	  --matcha-50:  #f3f8f3;
	    --matcha-100: #e4f0e4;
	    --matcha-200: #c8e1c8;
	    --matcha-300: #a6cfaa;
  	  --matcha-400: #86bd8c;
	    --matcha-500: #6aa972;
  	  --matcha-600: #4f8f58;
  	  --matcha-700: #3d6f45;
  	  --matcha-800: #2f5535;
  	  --matcha-900: #1f3a25;

  	  --bg-main: var(--matcha-50);
  	  --bg-card: var(--matcha-100);
  	  --text-main: var(--matcha-900);
  	  --accent: var(--matcha-500);
	  }

	  body {
  	  background-color: var(--bg-main);
	    color: var(--text-main);
  	  font-family: "Inter", system-ui, sans-serif;
	  }

	  .card {
  	  background: var(--bg-card);
  	  border-radius: 16px;
  	  padding: 16px;
  	  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
	  }

	  .button {
  	  background: var(--accent);
  	  color: white;
  	  border: none;
  	  padding: 10px 16px;
  	  border-radius: 12px;
  	  cursor: pointer;
	  }

	  .button:hover {
  	  filter: brightness(1.05);
	}
}
